mapper.select:
select id, MIX_AREA, PARAM_CODE, PARAM_NAME,PARAM_VALUE,REGULAR_EXPRESSION,ERROR_TIPS, remark, del_flag, create_by, create_time, update_by, update_time from T_SCHEDULE_PARAMS where del_flag = '0' and INSTR(PARAM_CODE, #{paramCode}) > 0 and INSTR(PARAM_NAME, #{paramName}) > 0 and MIX_AREA=#{mixArea}
order by mix_area
order by ${orderStr}
